import type { DiscountFormType, DiscountTierType } from "./types";

export const DEFAULT_DISCOUNT_TIERS: DiscountTierType[] = [
  {
    id: "tier-1",
    minQuantity: 2,
    discountValue: 10,
    discountType: "percentage",
    badgeLabel: "Save 10%",
  },
  {
    id: "tier-2",
    minQuantity: 3,
    discountValue: 15,
    discountType: "percentage",
    badgeLabel: "Popular",
    highlighted: true,
  },
  {
    id: "tier-3",
    minQuantity: 5,
    discountValue: 25,
    discountType: "percentage",
    badgeLabel: "Best Value",
  },
];

export const INITIAL_DISCOUNT_FORM: DiscountFormType = {
  title: "Tiered Volume Bundle Discount",
  code: "VOLUMEBUNDLE",
  method: "automatic",
  startsAt: "2026-09-01",
  endsAt: "2026-12-31",
  combinesWithShipping: true,
  combinesWithProductDiscounts: false,
  tiers: DEFAULT_DISCOUNT_TIERS,
  appliesTo: "specific_collections",
  selectedCollectionNames: ["Autumn Apparel", "Accessories", "Footwear"],
};

import * as React from "react";
import {
  Page,
  BlockStack,
  Banner,
  SaveBar,
} from "@xco-agency/corex-ui";
import { INITIAL_DISCOUNT_FORM } from "../constants";
import { DiscountGeneralCard } from "../partials/DiscountGeneralCard";
import { DiscountTiersCard } from "../partials/DiscountTiersCard";
import { TargetCollectionsCard } from "../partials/TargetCollectionsCard";
import { TierPreviewSidebarCard } from "../partials/TierPreviewSidebarCard";
import type { DiscountFormType, DiscountMethodType, DiscountTierType } from "../types";

export function DiscountRulesExample() {
  const [form, setForm] = React.useState<DiscountFormType>(INITIAL_DISCOUNT_FORM);
  const [isDirty, setIsDirty] = React.useState(false);
  const [isSaving, setIsSaving] = React.useState(false);
  const [notification, setNotification] = React.useState<string | null>(null);

  const updateField = <K extends keyof DiscountFormType>(
    field: K,
    val: DiscountFormType[K],
  ) => {
    setForm((prev) => ({ ...prev, [field]: val }));
    setIsDirty(true);
  };

  const handleUpdateTier = (id: string, updates: Partial<DiscountTierType>) => {
    const next = form.tiers.map((t) => (t.id === id ? { ...t, ...updates } : t));
    updateField("tiers", next);
  };

  const handleAddTier = () => {
    const last = form.tiers[form.tiers.length - 1];
    const nextQty = (last?.minQuantity ?? 1) + 2;
    const nextDisc = (last?.discountValue ?? 5) + 10;
    const newTier: DiscountTierType = {
      id: `tier-${Date.now()}`,
      minQuantity: nextQty,
      discountValue: nextDisc,
      discountType: "percentage",
      badgeLabel: `Save ${nextDisc}%`,
    };
    updateField("tiers", [...form.tiers, newTier]);
  };

  const handleRemoveTier = (id: string) => {
    updateField(
      "tiers",
      form.tiers.filter((t) => t.id !== id),
    );
  };

  const handleSave = () => {
    setIsSaving(true);
    setTimeout(() => {
      setIsSaving(false);
      setIsDirty(false);
      setNotification("Volume discount rules saved and published!");
    }, 500);
  };

  const handleDiscard = () => {
    setForm(INITIAL_DISCOUNT_FORM);
    setIsDirty(false);
  };

  return (
    <Page
      heading="Tiered Volume Discount Rules"
      subheading="Encourage wholesale and multi-unit purchases with progressive quantity discounts."
      inlineSize="large"
    >
      <BlockStack gap="base">
        {notification && (
          <Banner
            tone="success"
            title={notification}
            onDismiss={() => setNotification(null)}
          />
        )}

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "minmax(0, 2fr) minmax(280px, 1fr)",
            gap: "var(--p-space-400, 16px)",
            alignItems: "start",
          }}
        >
          {/* Main Column */}
          <BlockStack gap="base">
            <DiscountGeneralCard
              title={form.title}
              code={form.code}
              method={form.method}
              startsAt={form.startsAt}
              endsAt={form.endsAt}
              onUpdateTitle={(val) => updateField("title", val)}
              onUpdateCode={(val) => updateField("code", val)}
              onUpdateMethod={(val: DiscountMethodType) => updateField("method", val)}
              onUpdateStartsAt={(val) => updateField("startsAt", val)}
              onUpdateEndsAt={(val) => updateField("endsAt", val)}
            />

            <DiscountTiersCard
              tiers={form.tiers}
              onUpdateTier={handleUpdateTier}
              onAddTier={handleAddTier}
              onRemoveTier={handleRemoveTier}
            />

            <TargetCollectionsCard
              appliesTo={form.appliesTo}
              collections={form.selectedCollectionNames}
              combinesWithShipping={form.combinesWithShipping}
              combinesWithProductDiscounts={form.combinesWithProductDiscounts}
              onUpdateAppliesTo={(val) => updateField("appliesTo", val)}
              onRemoveCollection={(name) =>
                updateField(
                  "selectedCollectionNames",
                  form.selectedCollectionNames.filter((n) => n !== name),
                )
              }
              onAddCollection={() =>
                updateField("selectedCollectionNames", [
                  ...form.selectedCollectionNames,
                  "New Seasonal Collection",
                ])
              }
              onUpdateCombinesShipping={(val) =>
                updateField("combinesWithShipping", val)
              }
              onUpdateCombinesProducts={(val) =>
                updateField("combinesWithProductDiscounts", val)
              }
            />
          </BlockStack>

          {/* Sidebar Column */}
          <TierPreviewSidebarCard tiers={form.tiers} method={form.method} />
        </div>

        {isDirty && (
          <SaveBar
            open={isDirty}
            onSave={handleSave}
            onDiscard={handleDiscard}
            loading={isSaving}
          />
        )}
      </BlockStack>
    </Page>
  );
}

export { DiscountRulesExample } from "./examples/DiscountRulesExample";
export type {
  DiscountFormType,
  DiscountMethodType,
  DiscountTierType,
  DiscountType,
} from "./types";

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  TextField,
  Select,
} from "@xco-agency/corex-ui";
import type { DiscountMethodType } from "../types";

type DiscountGeneralCardPropsType = {
  title: string;
  code: string;
  method: DiscountMethodType;
  startsAt: string;
  endsAt?: string;
  onUpdateTitle: (title: string) => void;
  onUpdateCode: (code: string) => void;
  onUpdateMethod: (method: DiscountMethodType) => void;
  onUpdateStartsAt: (startsAt: string) => void;
  onUpdateEndsAt: (endsAt: string) => void;
};

export function DiscountGeneralCard({
  title,
  code,
  method,
  startsAt,
  endsAt,
  onUpdateTitle,
  onUpdateCode,
  onUpdateMethod,
  onUpdateStartsAt,
  onUpdateEndsAt,
}: DiscountGeneralCardPropsType) {
  const methodOptions = [
    { label: "Automatic discount (applied at checkout)", value: "automatic" },
    { label: "Discount code (customer enters code)", value: "code" },
  ];

  return (
    <Card>
      <BlockStack gap="base">
        <BlockStack gap="small-400">
          <Text as="h3" fontWeight="semibold">
            Discount Configuration
          </Text>
          <Text color="subdued" variant="bodySm">
            General details, discount method, and active duration.
          </Text>
        </BlockStack>

        <TextField
          label="Internal Title"
          value={title}
          onChange={onUpdateTitle}
          placeholder="e.g. Volume Tiered Breaks Q4"
        />

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "1fr 1fr",
            gap: "var(--p-space-400, 16px)",
          }}
        >
          <Select
            label="Method"
            value={method}
            options={methodOptions}
            onChange={(val) => onUpdateMethod(val as DiscountMethodType)}
          />

          {method === "code" ? (
            <TextField
              label="Discount Code"
              value={code}
              onChange={onUpdateCode}
              placeholder="e.g. TIERDEAL"
            />
          ) : (
            <TextField
              label="Cart Notice Badge"
              value="Applied automatically"
              disabled
              helpText="Merchants will see volume tags automatically in cart."
            />
          )}
        </div>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "1fr 1fr",
            gap: "var(--p-space-400, 16px)",
          }}
        >
          <TextField
            label="Start Date"
            type="date"
            value={startsAt}
            onChange={onUpdateStartsAt}
          />
          <TextField
            label="End Date (Optional)"
            type="date"
            value={endsAt ?? ""}
            onChange={onUpdateEndsAt}
          />
        </div>
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  TextField,
  NumberField,
  Select,
  Table,
  Divider,
} from "@xco-agency/corex-ui";
import type { DiscountTierType, DiscountType } from "../types";

type DiscountTiersCardPropsType = {
  tiers: DiscountTierType[];
  onUpdateTier: (id: string, updates: Partial<DiscountTierType>) => void;
  onAddTier: () => void;
  onRemoveTier: (id: string) => void;
};

export function DiscountTiersCard({
  tiers,
  onUpdateTier,
  onAddTier,
  onRemoveTier,
}: DiscountTiersCardPropsType) {
  const typeOptions = [
    { label: "Percentage off (%)", value: "percentage" },
    { label: "Fixed amount off ($)", value: "fixed_amount" },
  ];

  return (
    <Card>
      <BlockStack gap="base">
        <InlineStack justifyContent="space-between" alignItems="center">
          <BlockStack gap="small-400">
            <Text as="h3" fontWeight="semibold">
              Quantity Break Tiers
            </Text>
            <Text color="subdued" variant="small">
              Define the minimum quantities and corresponding discounts customers receive.
            </Text>
          </BlockStack>
          <Badge tone="info">{tiers.length} Tiers Configured</Badge>
        </InlineStack>

        <Divider />

        <Table>
          <Table.HeaderRow>
            <Table.Header>Tier</Table.Header>
            <Table.Header>Min. Quantity</Table.Header>
            <Table.Header>Discount Type</Table.Header>
            <Table.Header>Discount Value</Table.Header>
            <Table.Header>Badge Label (Optional)</Table.Header>
            <Table.Header>Actions</Table.Header>
          </Table.HeaderRow>
          <Table.Body>
            {tiers.map((tier, idx) => (
              <Table.Row key={tier.id}>
                <Table.Cell>
                  <Badge tone={tier.highlighted ? "success" : "neutral"}>
                    Tier {idx + 1}
                  </Badge>
                </Table.Cell>

                <Table.Cell>
                  <div style={{ maxWidth: "110px" }}>
                    <NumberField
                      label="Minimum Quantity"
                      labelAccessibilityVisibility="exclusive"
                      value={String(tier.minQuantity)}
                      min={1}
                      onChange={(val) =>
                        onUpdateTier(tier.id, {
                          minQuantity: Math.max(1, Number(val) || 1),
                        })
                      }
                    />
                  </div>
                </Table.Cell>

                <Table.Cell>
                  <div style={{ minWidth: "170px" }}>
                    <Select
                      label="Discount Type"
                      labelAccessibilityVisibility="exclusive"
                      value={tier.discountType}
                      options={typeOptions}
                      onChange={(val) =>
                        onUpdateTier(tier.id, {
                          discountType: val as DiscountType,
                        })
                      }
                    />
                  </div>
                </Table.Cell>

                <Table.Cell>
                  <div style={{ maxWidth: "120px" }}>
                    <NumberField
                      label="Discount Value"
                      labelAccessibilityVisibility="exclusive"
                      prefix={
                        tier.discountType === "fixed_amount" ? "$" : undefined
                      }
                      suffix={
                        tier.discountType === "percentage" ? "%" : undefined
                      }
                      value={String(tier.discountValue)}
                      min={0}
                      onChange={(val) =>
                        onUpdateTier(tier.id, {
                          discountValue: Math.max(0, Number(val) || 0),
                        })
                      }
                    />
                  </div>
                </Table.Cell>

                <Table.Cell>
                  <div style={{ minWidth: "140px" }}>
                    <TextField
                      label="Badge Label"
                      labelAccessibilityVisibility="exclusive"
                      placeholder="e.g. Popular"
                      value={tier.badgeLabel ?? ""}
                      onChange={(val) =>
                        onUpdateTier(tier.id, { badgeLabel: val })
                      }
                    />
                  </div>
                </Table.Cell>

                <Table.Cell>
                  <Button
                    variant="tertiary"
                    tone="critical"
                    disabled={tiers.length <= 1}
                    onClick={() => onRemoveTier(tier.id)}
                  >
                    Remove
                  </Button>
                </Table.Cell>
              </Table.Row>
            ))}
          </Table.Body>
        </Table>

        <InlineStack justifyContent="flex-start">
          <Button variant="secondary" onClick={onAddTier}>
            + Add Tier Break
          </Button>
        </InlineStack>
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Select,
  Checkbox,
  Divider,
} from "@xco-agency/corex-ui";

type TargetCollectionsCardPropsType = {
  appliesTo: "all_products" | "specific_collections";
  collections: string[];
  combinesWithShipping: boolean;
  combinesWithProductDiscounts: boolean;
  onUpdateAppliesTo: (val: "all_products" | "specific_collections") => void;
  onRemoveCollection: (name: string) => void;
  onAddCollection: () => void;
  onUpdateCombinesShipping: (val: boolean) => void;
  onUpdateCombinesProducts: (val: boolean) => void;
};

export function TargetCollectionsCard({
  appliesTo,
  collections,
  combinesWithShipping,
  combinesWithProductDiscounts,
  onUpdateAppliesTo,
  onRemoveCollection,
  onAddCollection,
  onUpdateCombinesShipping,
  onUpdateCombinesProducts,
}: TargetCollectionsCardPropsType) {
  const scopeOptions = [
    { label: "Specific collections only", value: "specific_collections" },
    { label: "All products in store", value: "all_products" },
  ];

  return (
    <Card>
      <BlockStack gap="base">
        <BlockStack gap="small-400">
          <Text as="h3" fontWeight="semibold">
            Applies To & Combinations
          </Text>
          <Text color="subdued" variant="bodySm">
            Choose which catalog items trigger this tiered volume pricing.
          </Text>
        </BlockStack>

        <Select
          label="Catalog Scope"
          value={appliesTo}
          options={scopeOptions}
          onChange={(val) =>
            onUpdateAppliesTo(val as "all_products" | "specific_collections")
          }
        />

        {appliesTo === "specific_collections" && (
          <BlockStack gap="small-200">
            <Text variant="bodySm" fontWeight="semibold">
              Selected Collections
            </Text>
            <InlineStack gap="small-200" wrap>
              {collections.map((name) => (
                <Badge key={name} tone="info">
                  {name}
                </Badge>
              ))}
            </InlineStack>
            <InlineStack justifyContent="flex-start">
              <Button variant="secondary" icon="search" onClick={onAddCollection}>
                Browse Collections
              </Button>
            </InlineStack>
          </BlockStack>
        )}

        <Divider />

        <BlockStack gap="small-200">
          <Text variant="bodySm" fontWeight="semibold">
            Discount Combinations
          </Text>
          <Checkbox
            label="Combine with free shipping discounts"
            checked={combinesWithShipping}
            onChange={onUpdateCombinesShipping}
          />
          <Checkbox
            label="Combine with other product discounts"
            checked={combinesWithProductDiscounts}
            onChange={onUpdateCombinesProducts}
          />
        </BlockStack>
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Box,
  Divider,
} from "@xco-agency/corex-ui";
import type { DiscountTierType } from "../types";

type TierPreviewSidebarCardPropsType = {
  tiers: DiscountTierType[];
  method: string;
};

export function TierPreviewSidebarCard({
  tiers,
  method,
}: TierPreviewSidebarCardPropsType) {
  // Simulated base product price $40.00
  const BASE_PRICE = 40.0;

  return (
    <BlockStack gap="base">
      <Card>
        <BlockStack gap="base">
          <Text as="h3" fontWeight="semibold">
            Storefront Table Preview
          </Text>
          <Text color="subdued" variant="bodySm">
            This live widget simulates how your volume break table displays on product pages.
          </Text>

          <Box
            padding="base"
            background="subdued"
            borderRadius="base"
            borderWidth="small-100"
            borderColor="subdued"
            borderStyle="solid"
          >
            <BlockStack gap="small">
              <Text fontWeight="semibold" variant="bodySm">
                Buy More, Save More
              </Text>

              {tiers.map((t) => {
                const discountAmount =
                  t.discountType === "percentage"
                    ? (BASE_PRICE * t.discountValue) / 100
                    : t.discountValue;
                const priceEach = Math.max(0, BASE_PRICE - discountAmount);

                return (
                  <Box
                    key={t.id}
                    padding="small"
                    background="base"
                    borderRadius="base"
                    borderWidth="small-100"
                    borderColor={t.highlighted ? "base" : "subdued"}
                    borderStyle="solid"
                  >
                    <InlineStack justifyContent="space-between" alignItems="center">
                      <BlockStack gap="small-500">
                        <InlineStack gap="small-200" alignItems="center">
                          <Text fontWeight="bold" variant="bodySm">
                            Buy {t.minQuantity}+
                          </Text>
                          {t.badgeLabel && (
                            <Badge tone={t.highlighted ? "success" : "info"}>
                              {t.badgeLabel}
                            </Badge>
                          )}
                        </InlineStack>
                        <Text color="subdued" variant="bodySm">
                          {t.discountValue}
                          {t.discountType === "percentage" ? "%" : "$"} discount
                        </Text>
                      </BlockStack>

                      <BlockStack gap="small-500" alignItems="end">
                        <Text fontWeight="bold" variant="bodySm">
                          ${priceEach.toFixed(2)} / ea
                        </Text>
                        <span
                          style={{
                            textDecoration: "line-through",
                            color: "var(--p-color-text-subdued, #616161)",
                            fontSize: "11px",
                          }}
                        >
                          ${BASE_PRICE.toFixed(2)}
                        </span>
                      </BlockStack>
                    </InlineStack>
                  </Box>
                );
              })}
            </BlockStack>
          </Box>
        </BlockStack>
      </Card>

      <Card>
        <BlockStack gap="small">
          <Text as="h3" fontWeight="semibold">
            Summary
          </Text>
          <Divider />
          <InlineStack justifyContent="space-between">
            <Text color="subdued" variant="bodySm">
              Application
            </Text>
            <Text fontWeight="semibold" variant="bodySm">
              {method === "automatic" ? "Automatic in Cart" : "Via Promo Code"}
            </Text>
          </InlineStack>
          <InlineStack justifyContent="space-between">
            <Text color="subdued" variant="bodySm">
              Max Volume Break
            </Text>
            <Text fontWeight="semibold" variant="bodySm">
              {Math.max(...tiers.map((t) => t.discountValue), 0)}%
            </Text>
          </InlineStack>
        </BlockStack>
      </Card>
    </BlockStack>
  );
}

export type DiscountType = "percentage" | "fixed_amount";

export type DiscountTierType = {
  id: string;
  minQuantity: number;
  discountValue: number;
  discountType: DiscountType;
  badgeLabel?: string;
  highlighted?: boolean;
};

export type DiscountMethodType = "automatic" | "code";

export type DiscountFormType = {
  title: string;
  code: string;
  method: DiscountMethodType;
  startsAt: string;
  endsAt?: string;
  combinesWithShipping: boolean;
  combinesWithProductDiscounts: boolean;
  tiers: DiscountTierType[];
  appliesTo: "all_products" | "specific_collections";
  selectedCollectionNames: string[];
};
